  // 3. 几何辅助函数
  // ===================================================================
  // 半透明“幽灵”填充材质（组装态 opacity=1 → 爆炸态 0.08，由动画 lerp）
  function ghostMat() {
    return new THREE.MeshBasicMaterial({ color: GHOST_COLOR, transparent: true, opacity: 1 });
  }
  // 生成 EdgesGeometry 线框并作为 mesh 的子节点（随 mesh 变换）
  function addEdges(mesh, color = BLUE) {
    const seg = new THREE.LineSegments(
      new THREE.EdgesGeometry(mesh.geometry, 1),
      new THREE.LineBasicMaterial({ color })
    );
    mesh.add(seg);
    return seg;
  }
  // 生成 Box 网格（含描边），返回 mesh
  function addBox(group, w, h, d, x, y, z) {
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), ghostMat());
    mesh.position.set(x, y, z);
    addEdges(mesh);
    group.add(mesh);
    return mesh;
  }
  // 带切角的外轮廓（CCW）：60×60，四角切角 3
  function chamferRectShape(size = SHELL_SIZE, chamfer = CHAMFER) {
    const s = new THREE.Shape();
    const h = size / 2, c = chamfer;
    s.moveTo(-h + c, -h);
    s.lineTo( h - c, -h);
    s.lineTo( h, -h + c);
    s.lineTo( h,  h - c);
    s.lineTo( h - c,  h);
    s.lineTo(-h + c,  h);
    s.lineTo(-h,  h - c);
    s.lineTo(-h, -h + c);
    s.closePath();
    return s;
  }
  // 矩形镂空路径（CW 绕向）
  function rectHole(x0, y0, x1, y1) {
    const p = new THREE.Path();
    p.moveTo(x0, y1); p.lineTo(x1, y1); p.lineTo(x1, y0); p.lineTo(x0, y0);
    p.closePath();
    return p;
  }
  // 圆形路径：cw=true 表示 CW（用作孔洞）
  function circlePath(cx, cy, r, segs = 32, cw = false) {
    const p = new THREE.Path();
    for (let i = 0; i <= segs; i++) {
      const a = (i / segs) * Math.PI * 2 * (cw ? -1 : 1);
      const x = cx + r * Math.cos(a), y = cy + r * Math.sin(a);
      if (i === 0) p.moveTo(x, y); else p.lineTo(x, y);
    }
    return p;
  }
  // 在 XY 平面挤压形状，再旋转到 XZ 平面（shape 的 +y → 世界 +z 即“后”），
  // 挤压深度沿世界 Y，居中于原点
  function extrudeToXZ(shape, depth) {
    const g = new THREE.ExtrudeGeometry(shape, { depth, bevelEnabled: false, curveSegments: 24 });
    g.rotateX(Math.PI / 2);
    g.translate(0, depth / 2, 0);
    return g;
  }

  // ===================================================================
  // 4. TOP SHELL（上壳）—— 复合结构
  //    外轮廓带切角 + 真镂空孔（HD NOTCH / 快门开口槽）+ 下沉凹槽 + 箭头
  // ===================================================================
  function createTopShell() {
    const group = new THREE.Group();
    const topShellMats = [];

    const shape = chamferRectShape();
    // (a) HD NOTCH：左上角 4×4 方形真镂空
    shape.holes.push(rectHole(-28, 24, -24, 28));
