    const geo = extrudeToXZ(shape, SHELL_DEPTH);
    const shell = new THREE.Mesh(geo, ghostMat());
    topShellMats.push({ mat: shell.material, from: 1, to: 0.08 });
    addEdges(shell);
    group.add(shell);

    // (b) 标签凹槽：上半部中央 36×22 下沉浅凹槽（薄盒略低于表面，仅描边可见）
    topShellMats.push({ mat: addBox(group, 36, 0.3, 22, 0, 0.8, 19).material, from: 1, to: 0.08 });
    // (c) 内部凹槽：标签凹槽下方 20×10 滑盖凹陷区
    topShellMats.push({ mat: addBox(group, 20, 0.3, 10, 0, 0.8, 2).material, from: 1, to: 0.08 });

    // (e) 箭头标记：Shutter 开口右侧的小三角（指示滑开方向 +X）
