      new THREE.Vector3(-16.5, 1.02, -21),
      new THREE.Vector3(-12.5, 1.02, -22),
      new THREE.Vector3(-16.5, 1.02, -23),
    ];
    const arrow = new THREE.LineLoop(
      new THREE.BufferGeometry().setFromPoints(arrowPts), EDGE_MAT);
    group.add(arrow);

    group.userData.mats = topShellMats;
    return group;
