// 几何验证脚本：复用 HTML 中的形状构建逻辑，验证三角化/孔洞包含/对齐
const THREE = require('./three.min.js');

const DEG = Math.PI / 180;
const CHAMFER = 3;
const SLOT_W = 6, SLOT_D = 14, SLOT_X = -22, SLOT_Z = -22;

function chamferRectShape(size = 60, chamfer = CHAMFER) {
  const s = new THREE.Shape();
  const h = size / 2, c = chamfer;
  s.moveTo(-h + c, -h);
  s.lineTo( h - c, -h);
  s.lineTo( h, -h + c);
  s.lineTo( h,  h - c);
  s.lineTo( h - c,  h);
  s.lineTo(-h + c,  h);
  s.lineTo(-h,  h - c);
  s.lineTo(-h, -h + c);
  s.closePath();
  return s;
}
function rectHole(x0, y0, x1, y1) {
  const p = new THREE.Path();
  p.moveTo(x0, y1); p.lineTo(x1, y1); p.lineTo(x1, y0); p.lineTo(x0, y0);
  p.closePath();
  return p;
}
function circlePath(cx, cy, r, segs = 32, cw = false) {
  const p = new THREE.Path();
  for (let i = 0; i <= segs; i++) {
    const a = (i / segs) * Math.PI * 2 * (cw ? -1 : 1);
    const x = cx + r * Math.cos(a), y = cy + r * Math.sin(a);
    if (i === 0) p.moveTo(x, y); else p.lineTo(x, y);
  }
  return p;
}
function extrudeToXZ(shape, depth) {
  const g = new THREE.ExtrudeGeometry(shape, { depth, bevelEnabled: false, curveSegments: 24 });
  g.rotateX(Math.PI / 2);
  g.translate(0, depth / 2, 0);
  return g;
}
function createLinerShape(R = 27, r = 6) {
  const s = new THREE.Shape();
  const A = [R * Math.cos(205 * DEG), R * Math.sin(205 * DEG)];
  const B = [R * Math.cos(230 * DEG), R * Math.sin(230 * DEG)];
  s.moveTo(A[0], A[1]);
  s.lineTo(A[0], -9);
  s.lineTo(B[0], -9);
  s.lineTo(B[0], B[1]);
  for (let d = 235; d <= 565; d += 5) s.lineTo(R * Math.cos(d * DEG), R * Math.sin(d * DEG));
  s.closePath();
  s.holes.push(circlePath(0, 0, r, 32, true));
  return s;
}

let pass = 0, fail = 0;
function check(name, cond) {
  if (cond) { pass++; console.log('  PASS:', name); }
  else { fail++; console.log('  FAIL:', name); }
}

// ---------- 1. 三角化（earcut）验证：所有复合 Shape 可正常生成 ExtrudeGeometry ----------
console.log('== 1. ExtrudeGeometry 构建 ==');
const shapes = {
  'TOP SHELL (2 holes)': (() => { const s = chamferRectShape(); s.holes.push(rectHole(-28,24,-24,28)); s.holes.push(rectHole(SLOT_X-3, SLOT_Z-7, SLOT_X+3, SLOT_Z+7)); return s; })(),
  'BOTTOM SHELL (3 holes)': (() => { const s = chamferRectShape(); s.holes.push(circlePath(0,0,7,32,true)); s.holes.push(rectHole(25,25,28,28)); s.holes.push(rectHole(SLOT_X-3, SLOT_Z-7, SLOT_X+3, SLOT_Z+7)); return s; })(),
  'DUST LINER (C + 1 hole)': createLinerShape(),
  'HUB (1 circle + 1 rect hole)': (() => { const s = circlePath(0,0,5,40,false); s.holes.push(circlePath(0,0,1.6,24,true)); s.holes.push(rectHole(1.4,-0.8,3.0,0.8)); return s; })(),
  'SHUTTER (1 rect hole)': (() => { const s = new THREE.Shape(); s.moveTo(-11,-8); s.lineTo(11,-8); s.lineTo(11,8); s.lineTo(-11,8); s.closePath(); s.holes.push(rectHole(-11,-7,-5,7)); return s; })(),
  'RECESS ANNULUS (1 hole)': (() => { const s = circlePath(0,0,22,48,false); s.holes.push(circlePath(0,0,7,32,true)); return s; })(),
};
for (const [name, shape] of Object.entries(shapes)) {
  try {
    const g = extrudeToXZ(shape, name === 'DUST LINER (C + 1 hole)' ? 0.05 : (name === 'HUB (1 circle + 1 rect hole)' ? 0.35 : (name === 'RECESS ANNULUS (1 hole)' ? 0.3 : (name === 'SHUTTER (1 rect hole)' ? 1 : 2))));
    const pos = g.attributes.position;
    let ok = pos.count > 3;
    // 验证三角面片数量为正
    ok = ok && g.index ? g.index.count > 0 : true;
    check(`${name}: ${pos.count} verts, ${g.index ? g.index.count : '?'} idx`, ok);
    // 验证顶点范围合理（无 NaN / 巨大值）
    let bad = false;
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
      if (!isFinite(x) || !isFinite(y) || !isFinite(z) || Math.abs(x) > 60 || Math.abs(z) > 60 || Math.abs(y) > 3) bad = true;
    }
    check(`${name}: 顶点范围合理`, !bad);
  } catch (e) {
    check(`${name}: 构建异常 → ${e.message}`, false);
  }
}

// ---------- 2. 孔洞包含关系（孔洞顶点必须在轮廓内部） ----------
console.log('== 2. 孔洞包含关系 ==');
function pointInShape(shape, px, py) {
  // 射线法
  const pts = shape.getPoints(60);
  let inside = false;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
    const xi = pts[i].x, yi = pts[i].y, xj = pts[j].x, yj = pts[j].y;
    if ((yi > py) !== (yj > py) && px < (xj - xi) * (py - yi) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}
function holeVertices(shape) {
  const out = [];
  for (const h of shape.holes) for (const p of h.getPoints(24)) out.push([p.x, p.y]);
  return out;
}
for (const [name, shape] of Object.entries(shapes)) {
  let allIn = true;
  for (const [hx, hy] of holeVertices(shape)) {
