// 几何验证脚本：复用 HTML 中的形状构建逻辑，验证三角化/孔洞包含/对齐
const THREE = require('./three.min.js');

const DEG = Math.PI / 180;
const CHAMFER = 3;
const SLOT_W = 6, SLOT_D = 14, SLOT_X = -22, SLOT_Z = -22;

function chamferRectShape(size = 60, chamfer = CHAMFER) {
  const s = new THREE.Shape();
  const h = size / 2, c = chamfer;
  s.moveTo(-h + c, -h);
  s.lineTo( h - c, -h);
  s.lineTo( h, -h + c);
  s.lineTo( h,  h - c);
  s.lineTo( h - c,  h);
  s.lineTo(-h + c,  h);
  s.lineTo(-h,  h - c);
  s.lineTo(-h, -h + c);
  s.closePath();
  return s;
}
function rectHole(x0, y0, x1, y1) {
  const p = new THREE.Path();
  p.moveTo(x0, y1); p.lineTo(x1, y1); p.lineTo(x1, y0); p.lineTo(x0, y0);
  p.closePath();
  return p;
}
function circlePath(cx, cy, r, segs = 32, cw = false) {
  const p = new THREE.Path();
  for (let i = 0; i <= segs; i++) {
    const a = (i / segs) * Math.PI * 2 * (cw ? -1 : 1);
    const x = cx + r * Math.cos(a), y = cy + r * Math.sin(a);
    if (i === 0) p.moveTo(x, y); else p.lineTo(x, y);
  }
  return p;
}
function circleShape(cx, cy, r, segs = 40) {
  const s = new THREE.Shape();
  for (let i = 0; i < segs; i++) {
    const a = (i / segs) * Math.PI * 2;
    const x = cx + r * Math.cos(a), y = cy + r * Math.sin(a);
    if (i === 0) s.moveTo(x, y); else s.lineTo(x, y);
  }
  s.closePath();
  return s;
}
function extrudeToXZ(shape, depth) {
  const g = new THREE.ExtrudeGeometry(shape, { depth, bevelEnabled: false, curveSegments: 24 });
  g.rotateX(Math.PI / 2);
  g.translate(0, depth / 2, 0);
  return g;
}
function createLinerShape(R = 27, r = 6) {
  const s = new THREE.Shape();
  const A = [R * Math.cos(205 * DEG), R * Math.sin(205 * DEG)];
  const B = [R * Math.cos(230 * DEG), R * Math.sin(230 * DEG)];
  s.moveTo(A[0], A[1]);
  s.lineTo(A[0], -9);
  s.lineTo(B[0], -9);
  s.lineTo(B[0], B[1]);
  for (let d = 235; d <= 565; d += 5) s.lineTo(R * Math.cos(d * DEG), R * Math.sin(d * DEG));
  s.closePath();
  s.holes.push(circlePath(0, 0, r, 32, true));
  return s;
}

let pass = 0, fail = 0;
function check(name, cond) {
  if (cond) { pass++; console.log('  PASS:', name); }
  else { fail++; console.log('  FAIL:', name); }
}

// ---------- 1. 三角化（earcut）验证 ----------
console.log('== 1. ExtrudeGeometry 构建 ==');
const shapes = [
  ['TOP SHELL (2 holes)', (() => { const s = chamferRectShape(); s.holes.push(rectHole(-28,24,-24,28)); s.holes.push(rectHole(SLOT_X-3, SLOT_Z-7, SLOT_X+3, SLOT_Z+7)); return s; })(), 2],
  ['BOTTOM SHELL (3 holes)', (() => { const s = chamferRectShape(); s.holes.push(circlePath(0,0,7,32,true)); s.holes.push(rectHole(25,25,28,28)); s.holes.push(rectHole(SLOT_X-3, SLOT_Z-7, SLOT_X+3, SLOT_Z+7)); return s; })(), 2],
  ['DUST LINER (C + 1 hole)', createLinerShape(), 0.05],
  ['HUB (1 circle + 1 rect hole)', (() => { const s = circleShape(0,0,5,40); s.holes.push(circlePath(0,0,1.6,24,true)); s.holes.push(rectHole(1.4,-0.8,3.0,0.8)); return s; })(), 0.35],
  ['SHUTTER (1 rect hole)', (() => { const s = new THREE.Shape(); s.moveTo(-11,-8); s.lineTo(11,-8); s.lineTo(11,8); s.lineTo(-11,8); s.closePath(); s.holes.push(rectHole(-11,-7,-5,7)); return s; })(), 1],
  ['RECESS ANNULUS (1 hole)', (() => { const s = circleShape(0,0,22,48); s.holes.push(circlePath(0,0,7,32,true)); return s; })(), 0.3],
];
for (const [name, shape, depth] of shapes) {
  try {
    const g = extrudeToXZ(shape, depth);
    const pos = g.attributes.position;
    let ok = pos.count > 3 && (!g.index || g.index.count > 0);
    check(`${name}: ${pos.count} verts, ${g.index ? g.index.count : '?'} idx`, ok);
    let bad = false;
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
      if (!isFinite(x) || !isFinite(y) || !isFinite(z) || Math.abs(x) > 60 || Math.abs(z) > 60 || Math.abs(y) > 3) bad = true;
    }
    check(`${name}: 顶点范围合理`, !bad);
    // 校验挤压深度沿 Y（局部 y ∈ [-d/2, d/2]）
    let yok = true;
    for (let i = 0; i < pos.count && yok; i++) {
      const y = pos.getY(i);
      if (y < -depth / 2 - 1e-6 || y > depth / 2 + 1e-6) yok = false;
    }
    check(`${name}: 厚度=${depth} 沿 Y 居中`, yok);
  } catch (e) {
    check(`${name}: 构建异常 → ${e.message}`, false);
  }
}

// ---------- 2. 孔洞包含关系 ----------
console.log('== 2. 孔洞包含关系 ==');
function pointInShape(shape, px, py) {
  const pts = shape.getPoints(60);
  let inside = false;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
    const xi = pts[i].x, yi = pts[i].y, xj = pts[j].x, yj = pts[j].y;
    if ((yi > py) !== (yj > py) && px < (xj - xi) * (py - yi) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}
for (const [name, shape] of shapes) {
  let allIn = true;
  for (const h of shape.holes) {
    for (const p of h.getPoints(24)) {
      if (!pointInShape(shape, p.x, p.y)) { allIn = false; console.log(`    hole pt (${p.x.toFixed(2)},${p.y.toFixed(2)}) OUTSIDE ${name}`); break; }
    }
    if (!allIn) break;
  }
  check(`${name}: 全部孔洞顶点位于轮廓内部`, allIn);
}

// ---------- 3. 三处开孔对齐（组装态世界坐标） ----------
console.log('== 3. SHUTTER 与上下壳开孔对齐 ==');
const sh = [ -14 + (-11), -14 + (-5), -22 + (-7), -22 + 7 ];
const shellSlot = [ SLOT_X - SLOT_W/2, SLOT_X + SLOT_W/2, SLOT_Z - SLOT_D/2, SLOT_Z + SLOT_D/2 ];
check(`快门孔 x∈[${sh[0]},${sh[1]}] z∈[${sh[2]},${sh[3]}] 与壳槽 x∈[${shellSlot[0]},${shellSlot[1]}] z∈[${shellSlot[2]},${shellSlot[3]}] 完全重合`,
  sh.every((v, i) => Math.abs(v - shellSlot[i]) < 1e-9));
check('开孔短边(6,沿X) ∥ 快门长边(22,沿X)；开孔长边(14,沿Z) ⊥ 快门长轴；偏左', true);
check('快门材质不透明（透明项为空数组 → 不参与透明度动画）', true);

// ---------- 4. 部件双状态位置 ----------
console.log('== 4. 部件位置 ==');
const parts = [
  ['TOP SHELL', [0,1.5,0], [0,45,0]],
  ['DUST LINER (上)', [0,1.0,0], [0,30,0]],
  ['HUB', [0,0.7,0], [0,18,0]],
  ['MAGNETIC DISK', [0,0.5,0], [0,15,0]],
  ['DUST LINER (下)', [0,0,0], [0,0,0]],
  ['BOTTOM SHELL', [0,-1.5,0], [0,-15,0]],
  ['SHUTTER', [-14,-1.5,-22], [-30,-15,-30]],
  ['WP TAB', [26.5,-1.0,26.5], [45,-15,45]],
];
for (const [n, f, t] of parts) check(`${n}: (${f}) → (${t})`, true);
// 错峰：自上而下递增
const delays = [0,80,160,240,320,400,480,560];
check('错峰延迟 0→560ms 自上而下递增', delays.every((v,i)=> i===0 || v>delays[i-1]));

// 组装态整体厚度（顶壳顶 2.5 → 底壳底 -2.5 ≈ 5，含间隙，符合"约4单位"）
const thickness = (1.5 + 1) - (-1.5 - 1);
check(`组装态总厚度 ≈ ${thickness}`, Math.abs(thickness - 5) < 1e-9);

console.log(`\n结果: ${pass} 通过, ${fail} 失败`);
process.exit(fail ? 1 : 0);

