  function advanceLabelTimeline(t) {
    const DASH_START = 0.2, DASH_DUR = 0.6, LABEL_START = 1.0, LABEL_GAP = 0.06;
    if (t >= DASH_START) {
      dashGroup.visible = true;
      dashMat.opacity = easeInOutCubic(clamp01((t - DASH_START) / DASH_DUR));
    }
    if (t >= LABEL_START) {
      labelGroup.visible = true;
      for (let i = 0; i < labels.length; i++) {
        if (t >= LABEL_START + i * LABEL_GAP) {
