  function triggerExplode() {
    if (animState !== 'assembled') return; // 动画进行中忽略
    hideLabels();
    animState = 'exploding';
    animT = 0;
    updateHint();
  }
  function triggerCollapse() {
    if (animState !== 'exploded') return;
    animState = 'collapsing';
    collapseDelay = 0.3; // 先让标注/虚线淡出（0.3s），再启动收回
    collapseT = 0;
    hideLabels();
    updateHint();
  }

  // ===================================================================
  // ANIMATION: updateAnimation —— 每帧推进位移 + 材质透明度插值
  // ===================================================================
  function updateAnimation(dt) {
    if (animState === 'exploding') {
      animT += dt;
      for (const p of parts) {
        const prog = clamp01((animT - p.delay) / DUR);
        if (prog > 0) {
          const e = easeInOutCubic(prog);
          p.group.position.lerpVectors(p.from, p.to, e);      // 位移
          for (const m of p.mats) {                            // 透明度同步
            m.mat.opacity = lerp(m.from, m.to, e);
          }
        }
      }
      if (animT >= DUR + MAX_DELAY / 1000) {
        animState = 'exploded';
        labelTL = { t: 0 }; // 爆炸完成：启动标注时序
      }
    } else if (animState === 'collapsing') {
      if (collapseDelay > 0) { collapseDelay -= dt; return; }
      collapseT += dt;
      for (const p of parts) {
        const prog = clamp01((collapseT - p.revDelay) / DUR); // 反向错峰
        if (prog > 0) {
          const e = 1 - easeInOutCubic(prog);                 // 1→0 收回
          p.group.position.lerpVectors(p.from, p.to, e);
          for (const m of p.mats) {
            m.mat.opacity = lerp(m.from, m.to, e);            // 反向插值回 1
          }
        }
