// 动画状态机集成模拟：复刻 HTML 中的 updateAnimation 逻辑
const THREE = require('./three.min.js');

const clamp01 = (v) => Math.min(1, Math.max(0, v));
const lerp = (a, b, t) => a + (b - a) * t;
function easeInOutCubic(t) { return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; }

// —— 与 HTML 相同的 parts 表 ——
const DUR = 3.0, MAX_DELAY = 560;
const defs = [
  ['TOP SHELL', [0,1.5,0], [0,45,0], 0, 0.08],
  ['DUST LINER (上)', [0,1.0,0], [0,30,0], 80, 0.08],
  ['HUB', [0,0.7,0], [0,18,0], 160, 0.08],
  ['MAGNETIC DISK', [0,0.5,0], [0,15,0], 240, 0.5],
  ['DUST LINER (下)', [0,0,0], [0,0,0], 320, 0.08],
  ['BOTTOM SHELL', [0,-1.5,0], [0,-15,0], 400, 0.08],
  ['SHUTTER', [-14,-1.5,-22], [-30,-15,-30], 480, null], // 不透明
  ['WP TAB', [26.5,-1.0,26.5], [45,-15,45], 560, 0.08],
];
const parts = defs.map(d => ({
  name: d[0],
  group: { pos: new THREE.Vector3(...d[1]) },
  from: new THREE.Vector3(...d[1]),
  to: new THREE.Vector3(...d[2]),
  delay: d[3] / 1000,
  revDelay: (MAX_DELAY - d[3]) / 1000,
  mats: d[4] === null ? [] : [{ opacity: 1, to: d[4] }],
}));

let animState = 'assembled', animT = 0, collapseDelay = 0, collapseT = 0;

function step(dt) {
  if (animState === 'exploding') {
    animT += dt;
    for (const p of parts) {
      const prog = clamp01((animT - p.delay) / DUR);
      if (prog > 0) {
        const e = easeInOutCubic(prog);
        p.group.pos.lerpVectors(p.from, p.to, e);
        for (const m of p.mats) m.opacity = lerp(1, m.to, e);
      }
    }
    if (animT >= DUR + MAX_DELAY / 1000) animState = 'exploded';
  } else if (animState === 'collapsing') {
    if (collapseDelay > 0) { collapseDelay -= dt; return; }
    collapseT += dt;
    for (const p of parts) {
      const prog = clamp01((collapseT - p.revDelay) / DUR);
      if (prog > 0) {
        const e = 1 - easeInOutCubic(prog);
        p.group.pos.lerpVectors(p.from, p.to, e);
        for (const m of p.mats) m.opacity = lerp(1, m.to, e);
      }
    }
    if (collapseT >= DUR + MAX_DELAY / 1000) {
      animState = 'assembled';
      for (const p of parts) { p.group.pos.copy(p.from); for (const m of p.mats) m.opacity = 1; }
    }
  }
}

let pass = 0, fail = 0;
const check = (n, c) => { if (c) { pass++; } else { fail++; console.log('  FAIL:', n); } };
const near = (a, b) => Math.abs(a - b) < 1e-6;

// 1. 初始组装态
check('初始: 全部在 from 位置', parts.every(p => p.group.pos.distanceTo(p.from) < 1e-9));
check('初始: 全部不透明', parts.every(p => p.mats.every(m => m.opacity === 1)));

// 2. 爆炸推进（模拟 3.6s，60fps）
animState = 'exploding';
for (let t = 0; t < 3.6; t += 1 / 60) step(1 / 60);
check('爆炸完成 → exploded', animState === 'exploded');
check('爆炸完成: TOP SHELL 在 y=45', near(parts[0].group.pos.y, 45));
check('爆炸完成: BOTTOM SHELL 在 y=-15', near(parts[5].group.pos.y, -15));
check('爆炸完成: SHUTTER 在 (-30,-15,-30)', parts[6].group.pos.distanceTo(new THREE.Vector3(-30,-15,-30)) < 1e-9);
check('爆炸完成: WP TAB 在 (45,-15,45)', parts[7].group.pos.distanceTo(new THREE.Vector3(45,-15,45)) < 1e-9);
check('爆炸完成: 壳体 opacity=0.08', near(parts[0].mats[0].opacity, 0.08));
check('爆炸完成: 磁片 opacity=0.5', near(parts[3].mats[0].opacity, 0.5));
check('爆炸完成: 快门不透明', parts[6].mats.length === 0);

// 3. 错峰验证：t=0.5s 时 TOP SHELL 已动、WP TAB 未动
{
  const before = parts.map(p => p.group.pos.y);
  const p0 = parts[0].group.pos.y;
  const p7 = parts[7].group.pos.y;
  check('错峰 t=0.5: TOP SHELL 已离开组装位', Math.abs(p0 - 1.5) > 0.1);
  check('错峰 t=0.5: WP TAB 尚未启动', Math.abs(p7 + 1.0) < 1e-9);
}

// 4. 收回（0.3s 等待 + 3.6s 动画）
animState = 'collapsing'; collapseDelay = 0.3; collapseT = 0;
for (let t = 0; t < 3.9; t += 1 / 60) step(1 / 60);
check('收回完成 → assembled', animState === 'assembled');
check('收回完成: 全部回到 from', parts.every(p => p.group.pos.distanceTo(p.from) < 1e-9));
check('收回完成: 全部 opacity=1', parts.every(p => p.mats.every(m => m.opacity === 1)));
// 收回等待期部件未动
animState = 'collapsing'; collapseDelay = 0.3; collapseT = 0;
step(0.3);
check('收回前 0.3s 部件保持爆炸态', near(parts[0].group.pos.y, 45));

// 5. 动画中按键忽略：exploding 时 trigger 被拒（状态不切换）
animState = 'exploding'; animT = 1.0;
const before2 = animState;
if (animState !== 'assembled' && animState !== 'exploded') { /* 忽略 */ }
check('exploding 中触发被忽略', animState === before2);

console.log(`\n结果: ${pass} 通过, ${fail} 失败`);
process.exit(fail ? 1 : 0);

