const THREE = require('./three.min.js');
const clamp01 = (v) => Math.min(1, Math.max(0, v));
const lerp = (a,b,t) => a+(b-a)*t;
function easeInOutCubic(t){return t<0.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;}
const DUR=3.0, MAX_DELAY=560;
const parts=[{name:'TOP',from:new THREE.Vector3(0,1.5,0),to:new THREE.Vector3(0,45,0),delay:0,revDelay:0.56,pos:new THREE.Vector3(0,1.5,0)}];
let st='assembled',animT=0,collapseDelay=0,collapseT=0;
function step(dt){
  if(st==='exploding'){
    animT+=dt;
    for(const p of parts){const pr=clamp01((animT-p.delay)/DUR);if(pr>0){const e=easeInOutCubic(pr);p.pos.lerpVectors(p.from,p.to,e);}}
    if(animT>=DUR+MAX_DELAY/1000)st='exploded';
  } else if(st==='collapsing'){
    if(collapseDelay>0){collapseDelay-=dt;return;}
    collapseT+=dt;
    for(const p of parts){const pr=clamp01((collapseT-p.revDelay)/DUR);if(pr>0){const e=1-easeInOutCubic(pr);p.pos.lerpVectors(p.from,p.to,e);}}
    if(collapseT>=DUR+MAX_DELAY/1000){st='assembled';for(const p of parts)p.pos.copy(p.from);}
  }
}
st='exploding';
